import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`landing-page-ad-match`,heroTitle:`Match your ads to your landing page in minutes`,heroSubtitle:`Perplexity Computer reads the page, identifies the core offer and messaging gaps, then writes a complete matched set - 5 Facebook ads, 5 Google ads, and a rewritten above-the-fold section so your ads and landing page tell the same story.`,inputUrlCta:`Match your ads to your landing page`,inputUrlPlaceholder:`example.com/landing-page`,inputUrlPrefill:`Go to {url} and create the requested assets for the business or page at that URL. Use this brief as context: Paste your landing page URL. Computer reads the page, identifies the core offer and messaging gaps, then writes a complete matched set - 5 Facebook ads, 5 Google ads, and a rewritten above-the-fold section so your ads and landing page tell the same story. (1) Research the offer, audience, and strongest angles from the page. (2) Benchmark effective examples in the category where helpful. (3) Write multiple tailored drafts with strong hooks, clear positioning, and relevant calls to action. (4) Explain the messaging strategy behind the recommended drafts. (5) Deliver the final copy in a clean, ready-to-use format with any recommended next tests.`,heroOverlaySteps:[`Reviewing the URL to understand the offer, audience, and positioning`,`Studying strong examples and patterns that fit the category`,`Writing tailored drafts, hooks, and messaging variations`,`Ready-to-use copy package with recommendations and next tests`],generatingSteps:[`Reviewing {url} to understand the offer, audience, and message`,`Designing an agent to benchmark strong examples and uncover the best angles`,`Configuring draft generation, variation testing, and editing passes`,`Packaging the work into a clean copy deck with recommendations and handoff notes`],featureSectionTitle:`From rough inputs to ready-to-use copy`,featureCardTitles:[`Connects to your growth workflow`,`Outputs your team can ship`],featureCardDescriptions:[`Computer breaks the work into focused tasks, spins up specialized agents, and matches each task to the model that fits it best.`,`Docs, Sheets, Notion, CRM notes, and campaign planning tools stay in the loop so the work moves straight into the tools your team already uses.`,`Research-backed messaging. Multiple draft options. Clear angles and calls to action. Computer gives you copy your team can refine or publish immediately.`],capabilitySectionTitle:`Your copy operator, on demand`,capabilitySectionSubtitle:`Paste your URL, step away, and come back to ready-to-use copy and recommendations.`,capabilityCards:[{title:`Context Research`,description:`Computer can review the offer, audience, and context so the writing stays specific to the business instead of sounding generic.`},{title:`Example Benchmarking`,description:`Computer can benchmark strong examples in the category to uncover useful hooks, formats, and positioning choices.`},{title:`Draft Generation`,description:`Computer can write multiple tailored drafts, variations, and supporting notes that are ready for review or direct use.`},{title:`Connect Your Tools`,description:`Computer can move drafts into Docs, Sheets, Notion, and planning tools so edits and approvals stay organized.`},{title:`Revision Support`,description:`Computer can tighten the strongest concepts, add new variations, and adapt the work for the next test or channel.`},{title:`Refresh and Reuse`,description:`Computer can revisit the brief later and quickly update the assets when the offer, audience, or context changes.`}]});export{t as default};
